13	 * Resolves the effective registration date and rolls it onto a business day, publishing it for
14	 * later steps. The effective date is the one supplied in the request, or the server's current date
15	 * when none was supplied. A supplied date later than the server's current date is rejected with 400
16	 * (see {@link FutureRegistrationDateException}); back-dating is allowed. When the effective date
17	 * falls on a weekend (Saturday or Sunday) or a listed public holiday it rolls forward to the next
18	 * non-holiday business day, so the stored {@code registrationDate} is always a business day.
19	 *
20	 * <p>Publishing the adjusted date here (before {@link CheckDailyLimit} and {@link BuildOwner}) means
21	 * every value derived from it stays consistent: the daily create-limit counts owners per adjusted
22	 * business day, and the membership number's year segment uses the adjusted year.
23	 */
24	public class ResolveRegistrationDate {
25	
26	    /** Fixed public holidays the business-day roll skips, in addition to weekends. */
27	    private static final Set<LocalDate> HOLIDAYS = Set.of(
28	            LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
29	            LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
30	            LocalDate.parse("2026-12-28"));
31	
32	    public void service(@Val OwnerFieldsDto request, Out<LocalDate> registrationDate)
33	            throws FutureRegistrationDateException {
34	        LocalDate effective = request.getRegistrationDate();
35	        if (effective == null) {
